<span class="line"><span style="color:#89DDFF;">    &quot;</span><span style="color:#F07178;">get:/shopping/?$</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> this.</span><span style="color:#BABED8;">getShoppingList</span><span style="color:#89DDFF;">,</span></span>
